def is_prime(x):
    i = 2
    while i * i <= x:
        if x % i == 0:
            return False
        i += 1
    return True

def is_strongly_composite(x):
    m = []
    i = 2
    while i * i <= x:
        while x % i == 0:
            x = x // i
            m.append(i)
        i += 1
    if not x == 1:
        m.append(i)
    return (len(m) >= 3 or (len(m) == 2 and m[0] == m[1]))

