        for (int i = c[0] - 3; i < x[0]; i++) {
            s.push_back(cur);
            cur++;
            if (cur == 'd') cur = 'a';
        }

        bool good = true;
        for (int j = 1; j < k; j++) {
            int dx = x[j] - x[j - 1];
            int dc = c[j] - c[j - 1];
