                good = false;
                break;
            }

            for (int i = 0; i < dc; i++)
                s.push_back('c' + j);
            for (int i = dc; i < dx; i++) {
                s.push_back(cur);
                cur++;
                if (cur == 'd') cur = 'a';
            }
        }

        if (good)
            cout << "YES" << endl << s << endl;
        else
            cout << "NO" << endl;
    }

    return 0;
