import threading

def main():
    n, l, r = map(int, input().split())

    g = [[] for i in range(0, n)]
    for i in range(0, n):
        a, b = map(int, input().split())
        a -= 1
        b -= 1
        g[a].append(b)
        g[b].append(a)

    res = 0
    used = [False for i in range(0, n)]

    def dfs(v):
        used[v] = True
        size = 1
        for to in g[v]:
            if not used[to]:
                size += dfs(to)
        return size

    for i in range(0, n):
        if not used[i]:
            size = dfs(i)
            if size <= l + r - 1:
                res ^= size // l

    if res:
        print("Alice")
    else:
        print("Bob")

